```javascript
function arrayManip(arr) {
  const n = arr.length;
  const result = new Array(n);
  const sorted = []; // maintains a sorted list of elements seen to the right

  // Traverse the array from right to left
  for (let i = n - 1; i >= 0; i--) {
    // Binary search: find the first element in sorted[] that is strictly greater than arr[i]
    let lo = 0, hi = sorted.length;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (sorted[mid] <= arr[i]) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    // lo is now the index of the least element greater than arr[i], or sorted.length if none
    result[i] = lo < sorted.length ? sorted[lo] : -1;

    // Insert arr[i] into the sorted array (binary search for insertion point)
    let ins = 0, insHi = sorted.length;
    while (ins < insHi) {
      const mid = Math.floor((ins + insHi) / 2);
      if (sorted[mid] < arr[i]) {
        ins = mid + 1;
      } else {
        insHi = mid;
      }
    }
    sorted.splice(ins, 0, arr[i]);
  }

  return result;
}
```

This is O(n log n) for the binary searches, but O(n²) overall due to the splice operation. For a truly O(n log n) solution, we'd need a balanced BST. But for practical purposes with typical array sizes in coding challenges, this should be fine.

