function arrayManip(arr) {
  return arr.map((val, i) => {
    // Get all elements to the right that are greater than val
    const greater = arr.slice(i + 1).filter(x => x > val);
    // Return the minimum of those, or -1 if none exist
    return greater.length > 0 ? Math.min(...greater) : -1;
  });
}
```

